const cmd = `
Write-Output "===== dsh-doublecheck README ====="
try { $x = Invoke-WebRequest -Uri 'https://raw.githubusercontent.com/PerryLink/dsh-doublecheck/main/README.md' -UseBasicParsing -TimeoutSec 20; $x.Content.Substring(0,[Math]::Min(4500,$x.Content.Length)) } catch { 'ERR ' + $_.Exception.Message }

Write-Output ""
Write-Output "===== dsh-grill-first package.json ====="
try { $x = Invoke-WebRequest -Uri 'https://raw.githubusercontent.com/InoriMutsumi/dsh-grill-first/main/package.json' -UseBasicParsing -TimeoutSec 20; $x.Content } catch { 'ERR ' + $_.Exception.Message }

Write-Output ""
Write-Output "===== dsh-grill-first npm dist-tags ====="
try { $x = Invoke-WebRequest -Uri 'https://registry.npmjs.org/dsh-grill-first' -UseBasicParsing -TimeoutSec 20; $j = $x.Content | ConvertFrom-Json; Write-Output ('latest=' + $j.'dist-tags'.latest); Write-Output ('versions=' + (($j.versions.PSObject.Properties.Name) -join ', ')); Write-Output ('modified=' + $j.time.modified) } catch { 'ERR ' + $_.Exception.Message }
`;
const r = await tools.pwsh({ description: "Fetch doublecheck README and grill-first package metadata", command: cmd, timeoutMs: 90000 });
if (r.kind === "foreground") console.log(r.stdout.text.slice(0, 12000));
